TASK
Decorate a promise with timeout, fallback, and cancellation behavior.

PUBLIC CONTRACT
Module: await load('./index.js'); default export pTimeout, named export TimeoutError.
pTimeout(inputPromise, options) returns a decorated promise with .clear() to cancel its timeout. milliseconds is a positive number; Infinity disables timeout. Before timeout, it adopts the input fulfillment or rejection. When timeout expires, default behavior rejects with TimeoutError; message may be a string, an Error to reject with, or false to resolve undefined. A fallback function can provide a value/promise instead, and exceptions from fallback reject the decorated promise. Cancelable input promises have their .cancel() method called on ordinary timeout.
customTimers supplies {setTimeout, clearTimeout} for controlled timing. The functions follow timer callback/delay and timer-handle conventions. A supplied AbortSignal cancels using its reason, including when already aborted. Settled operations clean up active timers and abort listeners. The input remains a promise whose rejection must be handled.

SOURCE index.js
   1: export class TimeoutError extends Error {
   2: 	name = 'TimeoutError';
   3: 
   4: 	constructor(message, options) {
   5: 		super(message, options);
   6: 		// V8-only, and it does exactly one thing here: it hides this constructor frame from the stack.
   7: 		// eslint-disable-next-line unicorn/no-useless-error-capture-stack-trace, unicorn/no-nonstandard-builtin-properties
   8: 		Error.captureStackTrace?.(this, TimeoutError);
   9: 	}
  10: }
  11: 
  12: const getAbortedReason = signal => signal.reason ?? new DOMException('This operation was aborted.', 'AbortError');
  13: 
  14: // `setTimeout` stores its delay in a 32-bit signed integer, so this is the largest delay it can represent.
  15: const maximumDelay = (2 ** 31) - 1;
  16: 
  17: export default function pTimeout(promise, options) {
  18: 	const {
  19: 		milliseconds,
  20: 		fallback,
  21: 		message,
  22: 		customTimers = {setTimeout, clearTimeout},
  23: 		signal,
  24: 	} = options;
  25: 
  26: 	let timer;
  27: 	let abortHandler;
  28: 
  29: 	const wrappedPromise = new Promise((resolve, reject) => {
  30: 		if (typeof milliseconds !== 'number' || Math.sign(milliseconds) !== 1) {
  31: 			throw new TypeError(`Expected \`milliseconds\` to be a positive number, got \`${milliseconds}\``);
  32: 		}
  33: 
  34: 		if (signal?.aborted) {
  35: 			reject(getAbortedReason(signal));
  36: 			// The input still needs a rejection handler even though cancellation won.
  37: 			// eslint-disable-next-line unicorn/prefer-then-catch
  38: 			promise.then(resolve, reject);
  39: 			return;
  40: 		}
  41: 
  42: 		if (signal) {
  43: 			abortHandler = () => {
  44: 				reject(getAbortedReason(signal));
  45: 			};
  46: 
  47: 			signal.addEventListener('abort', abortHandler, {once: true});
  48: 		}
  49: 
  50: 		// Use .then() instead of async IIFE to preserve stack traces
  51: 		// eslint-disable-next-line unicorn/prefer-then-catch
  52: 		promise.then(resolve, reject);
  53: 
  54: 		// A delay that `setTimeout` cannot represent never elapses, so there is nothing to time out. Without
  55: 		// this, `setTimeout` silently clamps anything above 2 ** 31 - 1 to 1ms and the timeout fires at once.
  56: 		if (milliseconds > maximumDelay) {
  57: 			return;
  58: 		}
  59: 
  60: 		// We create the error outside of `setTimeout` to preserve the stack trace.
  61: 		const timeoutError = new TimeoutError();
  62: 
  63: 		// `.call(undefined, ...)` is needed for custom timers to avoid context issues
  64: 		timer = customTimers.setTimeout.call(undefined, () => {
  65: 			if (fallback) {
  66: 				try {
  67: 					resolve(fallback());
  68: 				} catch (error) {
  69: 					reject(error);
  70: 				}
  71: 
  72: 				return;
  73: 			}
  74: 
  75: 			if (typeof promise.cancel === 'function') {
  76: 				promise.cancel();
  77: 			}
  78: 
  79: 			if (message === false) {
  80: 				resolve();
  81: 			} else if (message instanceof Error) {
  82: 				reject(message);
  83: 			} else {
  84: 				timeoutError.message = message ?? `Promise timed out after ${milliseconds} milliseconds`;
  85: 				reject(timeoutError);
  86: 			}
  87: 		}, milliseconds);
  88: 	});
  89: 
  90: 	const cancelablePromise = wrappedPromise.finally(() => {
  91: 		cancelablePromise.clear();
  92: 		if (abortHandler && signal) {
  93: 			signal.removeEventListener('abort', abortHandler);
  94: 		}
  95: 	});
  96: 
  97: 	cancelablePromise.clear = () => {
  98: 		// A timeout that never elapses creates no timer, and a custom `clearTimeout` is entitled to reject `undefined`.
  99: 		if (timer === undefined) {
 100: 			return;
 101: 		}
 102: 
 103: 		// `.call(undefined, ...)` is needed for custom timers to avoid context issues
 104: 		customTimers.clearTimeout.call(undefined, timer);
 105: 		timer = undefined;
 106: 	};
 107: 
 108: 	return cancelablePromise;
 109: }

OPTIONAL LINT/HINT CONTEXT
